class Solution {
public:
    int dx = -1, dy = -1, px = -1, py = -1;
    void walk(TreeNode* node, int parent, int depth, int x, int y) {
        if (!node) return;
        if (node->val == x) {
            dx = depth;
            px = parent;
        }
        if (node->val == y) {
            dy = depth;
            py = parent;
        }
        walk(node->left, node->val, depth + 1, x, y);
        walk(node->right, node->val, depth + 1, x, y);
    }
    bool isCousins(TreeNode* root, int x, int y) {
        walk(root, -1, 0, x, y);
        return dx == dy && px != py;
    }
};
